    """Fill each rectangular outline; use 7 for odd interior area and 2 for even."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0 = min(y for y, x in component)
            r1 = max(y for y, x in component)
            c0 = min(x for y, x in component)
            c1 = max(x for y, x in component)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            if not (all(grid[r0][x] == color and grid[r1][x] == color
                        for x in range(c0, c1 + 1)) and
                    all(grid[y][c0] == color and grid[y][c1] == color
                        for y in range(r0, r1 + 1))):
                continue
            interior_area = (r1 - r0 - 1) * (c1 - c0 - 1)
            fill = 7 if interior_area % 2 else 2
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    out[y][x] = fill
    return out
